% Standalone rel-spreading lab. Contract:
%   plans/2026-07-29-rel-spreading-lab-header.md
%
% Run from v6/prolog:
%   swipl -q -l labs/rel_spreading/lab.pl -g go -g halt
%
% Cross-language ground truth for the same eight cases is in RECEIPTS.md,
% regenerated by `bash probes/run_probes.sh`.

:- op(1150, xfx, <-).
:- op(1150, xfx, <+).
:- op(700,  xfx, :=).

:- use_module('0_spread').
:- use_module('1_rows').
:- use_module('2_hosts').
:- use_module('3_derived').
:- use_module('../../conformance/engine', [run_program/5, rel_deltas/3]).
:- use_module('../../compile/registry', [surface/5]).
:- use_module(library(lists)).

:- dynamic failed/0.
:- discontiguous check/2.

run_check(Name, Goal) :-
    ( catch(Goal, Error,
            ( format(user_error, "FAIL ~w threw ~q~n", [Name, Error]), fail ))
    -> format("PASS ~w~n", [Name])
    ;  format(user_error, "FAIL ~w~n", [Name]),
       assertz(failed)
    ).

go :-
    retractall(failed),
    forall(check(Name, Goal), run_check(Name, Goal)),
    ( failed -> halt(1) ; true ).

refuses(Goal, Refusal) :-
    catch(( Goal, fail ), unsupported_construct(Thrown), Thrown = Refusal).

% ════════════════════════════════════════════════════════════════════════════
% C1 declaration spread: compile-time column splice
% ════════════════════════════════════════════════════════════════════════════

base_decls([ col_type(a/2, id, int),
             col_type(a/2, name, text) ]).

spread_program(prog(Decls, Rules)) :-
    base_decls(Base),
    append(Base,
           [ spread_decl(b, [spread(a), col(extra, int)]),
             kind(b, log), keep(b, all) ],
           Decls),
    Rules = [ (b(Id, Name, 7) <+ a(Id, Name)) ].

hand_written_program(prog(Decls, Rules)) :-
    base_decls(Base),
    append(Base,
           [ col_type(b/3, id, int),
             col_type(b/3, name, text),
             col_type(b/3, extra, int),
             kind(b/3, log), keep(b/3, all) ],
           Decls),
    Rules = [ (b(Id, Name, 7) <+ a(Id, Name)) ].

check(c1_splice_produces_columns_in_source_order,
      ( spread_program(Sugared),
        expand_spread_program(Sugared, prog(Decls, _)),
        findall(Column, member(col_type(b/3, Column, _), Decls), Columns),
        Columns == [id, name, extra] )).

check(c1_splice_carries_the_source_column_types,
      ( spread_program(Sugared),
        expand_spread_program(Sugared, prog(Decls, _)),
        memberchk(col_type(b/3, id, int), Decls),
        memberchk(col_type(b/3, name, text), Decls),
        memberchk(col_type(b/3, extra, int), Decls) )).

% The whole rx-lowering claim in one check: after expansion the spread
% program IS the hand-written program, term for term. Nothing downstream of
% the expansion can tell them apart, so the lowering row is the hand-written
% program's lowering row.
check(c1_expanded_program_is_the_hand_written_program,
      ( spread_program(Sugared),
        hand_written_program(HandWritten),
        expand_spread_program(Sugared, Expanded),
        Expanded =@= HandWritten )).

check(c1_engine_gives_both_programs_the_same_tick_log,
      ( spread_program(Sugared),
        hand_written_program(HandWritten),
        expand_spread_program(Sugared, Expanded),
        Schedule = [ [ +a(1, "x") ], [ +a(2, "y") ] ],
        run_program(Expanded, [], Schedule, _, SpreadTicks),
        run_program(HandWritten, [], Schedule, _, HandTicks),
        rel_deltas(b/3, SpreadTicks, SpreadDeltas),
        rel_deltas(b/3, HandTicks, HandDeltas),
        SpreadDeltas == HandDeltas,
        SpreadDeltas == [ [ +b(1, "x", 7) ], [ +b(2, "y", 7) ], [] ] )).

% The spliced arity is COMPUTED, not written. This is the structural cost of
% the construct: a spread rel's arity stops being syntactic.
check(c1_spliced_arity_is_computed_not_written,
      ( spread_program(prog(Decls, _)),
        spread_arity(Decls, b, Arity),
        Arity =:= 3,
        \+ ( member(Decl, Decls), Decl = spread_decl(_, _),
             ground_arity_written(Decl) ) )).

ground_arity_written(spread_decl(Ref, _)) :- nonvar(Ref), Ref = _/_.

% A modifier written with a bare name gets the computed arity.
check(c1_bare_modifier_ref_takes_the_computed_arity,
      ( spread_program(Sugared),
        Sugared = prog(Decls, _),
        memberchk(kind(b, log), Decls),
        memberchk(keep(b, all), Decls),
        expand_spread_program(Sugared, prog(Expanded, _)),
        memberchk(kind(b/3, log), Expanded),
        memberchk(keep(b/3, all), Expanded) )).

% A modifier written with an explicit arity is CHECKED against the splice.
check(c1_written_arity_that_disagrees_is_refused,
      ( spread_program(prog(Decls0, Rules)),
        append(Decls0, [ keyed(b/2, [1]) ], Decls),
        refuses(expand_spread_program(prog(Decls, Rules), _),
                spread_arity_conflict(b, 2, 3)) )).

% Nested splice: a spread source may itself be a spread rel.
check(c1_nested_spread_source_resolves,
      ( base_decls(Base),
        append(Base,
               [ spread_decl(b, [spread(a), col(extra, int)]),
                 spread_decl(c, [spread(b), col(tail, text)]) ],
               Decls),
        expand_spread_program(prog(Decls, []), prog(Expanded, _)),
        findall(Column, member(col_type(c/4, Column, _), Expanded), Columns),
        Columns == [id, name, extra, tail] )).

check(c1_spread_cycle_is_refused,
      ( Decls = [ spread_decl(a, [spread(b), col(x, int)]),
                  spread_decl(b, [spread(a), col(y, int)]) ],
        refuses(expand_spread_program(prog(Decls, []), _),
                spread_cycle([a, b, a])) )).

check(c1_unknown_spread_source_is_refused,
      ( Decls = [ spread_decl(b, [spread(missing), col(extra, int)]) ],
        refuses(expand_spread_program(prog(Decls, []), _),
                spread_source_not_declared(missing)) )).

check(c1_spread_rel_may_not_also_declare_its_own_columns,
      ( base_decls(Base),
        append(Base,
               [ spread_decl(b, [spread(a)]),
                 col_type(b/2, id, int) ],
               Decls),
        refuses(expand_spread_program(prog(Decls, []), _),
                spread_and_explicit_columns(b)) )).

% ════════════════════════════════════════════════════════════════════════════
% C2 column collision
% ════════════════════════════════════════════════════════════════════════════

collision_decls(Decls) :-
    Decls = [ col_type(a/2, shared, int), col_type(a/2, only_a, text),
              col_type(x/2, shared, text), col_type(x/2, only_x, int),
              spread_decl(c, [spread(a), spread(x)]) ].

check(c2_column_collision_is_refused,
      ( collision_decls(Decls),
        refuses(expand_spread_program(prog(Decls, []), _),
                spread_column_collision(c, shared)) )).

check(c2_collision_is_refused_even_when_the_types_agree,
      ( Decls = [ col_type(a/1, shared, int),
                  col_type(x/1, shared, int),
                  spread_decl(c, [spread(a), spread(x)]) ],
        refuses(expand_spread_program(prog(Decls, []), _),
                spread_column_collision(c, shared)) )).

check(c2_a_collision_with_an_explicit_column_is_refused,
      ( base_decls(Base),
        append(Base, [ spread_decl(c, [spread(a), col(id, text)]) ], Decls),
        refuses(expand_spread_program(prog(Decls, []), _),
                spread_column_collision(c, id)) )).

% The graded negative: TypeScript's object spread resolves this collision
% silently by last-wins (RECEIPTS.md C2, tsc exit 0). Modelled here to show
% what the refusal buys: last-wins DROPS a column, so the spliced arity
% changes with the write order and the positional program changes under it.
last_wins_columns(Columns, Resolved) :-
    foldl(last_wins_step, Columns, [], Reversed),
    reverse(Reversed, Resolved).

last_wins_step(col(Name, Type), Acc, [col(Name, Type) | Stripped]) :-
    exclude(same_column_name(Name), Acc, Stripped).

same_column_name(Name, col(Name, _)).

check(c2_last_wins_would_have_dropped_a_column_silently,
      ( ColumnsInOrder = [ col(shared, int), col(only_a, text),
                           col(shared, text), col(only_x, int) ],
        last_wins_columns(ColumnsInOrder, Resolved),
        length(ColumnsInOrder, 4),
        length(Resolved, 3),
        memberchk(col(shared, text), Resolved),
        \+ memberchk(col(shared, int), Resolved) )).

check(c2_last_wins_result_depends_on_source_order,
      ( last_wins_columns([ col(shared, int), col(shared, text) ], Forward),
        last_wins_columns([ col(shared, text), col(shared, int) ], Backward),
        Forward \== Backward )).

% ════════════════════════════════════════════════════════════════════════════
% C3 row spread in a head
% ════════════════════════════════════════════════════════════════════════════

row_decls(Decls) :-
    Decls = [ col_type(a/2, id, int), col_type(a/2, name, text),
              col_type(c/3, id, int), col_type(c/3, name, text),
              col_type(c/3, extra, int), kind(c/3, log), keep(c/3, all),
              col_type(d/3, extra, int), col_type(d/3, id, int),
              col_type(d/3, name, text) ].

check(c3_marker_binds_one_fresh_variable_per_spliced_column,
      ( row_decls(Decls),
        Rule = (c(spread(Marker), 5) <- a(spread(Marker))),
        row_spread_widths(Decls, [Rule], Widths),
        Widths = [w(Bound, Width)],
        Bound == Marker,
        Width =:= 2 )).

check(c3_splice_shares_the_same_variables_between_head_and_body,
      ( row_decls(Decls),
        expand_row_spread_rules(Decls,
                                [ (c(spread(Marker), 5) <- a(spread(Marker))) ],
                                [ (Head <- Body) ]),
        Head =.. [c, HeadFirst, HeadSecond, 5],
        Body =.. [a, BodyFirst, BodySecond],
        HeadFirst == BodyFirst,
        HeadSecond == BodySecond )).

check(c3_spliced_rule_equals_the_hand_written_positional_rule,
      ( row_decls(Decls),
        expand_row_spread_rules(Decls,
                                [ (c(spread(Marker), 5) <- a(spread(Marker))) ],
                                [ Spliced ]),
        HandWritten = (c(Id, Name, 5) <- a(Id, Name)),
        Spliced =@= HandWritten )).

check(c3_explicit_slots_may_precede_the_marker,
      ( row_decls(Decls),
        expand_row_spread_rules(Decls,
                                [ (d(5, spread(Marker)) <- a(spread(Marker))) ],
                                [ Spliced ]),
        Spliced =@= (d(5, Id, Name) <- a(Id, Name)) )).

check(c3_head_arity_totality_is_enforced,
      ( row_decls(Decls),
        refuses(expand_row_spread_rules(Decls,
                                        [ (c(spread(Marker)) <- a(spread(Marker))) ],
                                        _),
                head_arity_mismatch(c, 2, 3)) )).

check(c3_marker_that_never_reaches_a_body_atom_is_refused,
      ( row_decls(Decls),
        refuses(expand_row_spread_rules(Decls,
                                        [ (c(spread(_Marker), 5) <- true) ],
                                        _),
                row_spread_unbound_in_head) )).

check(c3_two_body_widths_for_one_marker_are_refused,
      ( row_decls(Decls),
        refuses(expand_row_spread_rules(Decls,
                                        [ (c(spread(Marker), 5) <-
                                              a(spread(Marker)),
                                              c(spread(Marker)) ) ],
                                        _),
                row_spread_width_conflict(2, 3)) )).

check(c3_two_markers_in_one_atom_are_refused,
      ( row_decls(Decls),
        refuses(expand_row_spread_rules(Decls,
                                        [ (c(spread(_M1), 5) <-
                                              a(spread(_M2), spread(_M3))) ],
                                        _),
                multiple_row_spreads_in_atom(_)) )).

check(c3_a_body_width_source_with_no_declared_columns_is_refused,
      ( Decls = [ col_type(c/3, id, int), col_type(c/3, name, text),
                  col_type(c/3, extra, int) ],
        refuses(expand_row_spread_rules(Decls,
                                        [ (c(spread(Marker), 5) <-
                                              undeclared(spread(Marker))) ],
                                        _),
                row_spread_width_unknown(undeclared)) )).

check(c3_engine_runs_the_spliced_rule,
      ( row_decls(Decls),
        expand_row_spread_rules(Decls,
                                [ (c(spread(Marker), 5) <+ a(spread(Marker))) ],
                                Rules),
        run_program(prog(Decls, Rules), [], [ [ +a(1, "x") ] ], _, Ticks),
        rel_deltas(c/3, Ticks, Deltas),
        Deltas == [ [ +c(1, "x", 5) ], [] ] )).

% ════════════════════════════════════════════════════════════════════════════
% C4 width subtyping
% ════════════════════════════════════════════════════════════════════════════

width_decls(Decls) :-
    Decls = [ col_type(wide/3, id, int), col_type(wide/3, name, text),
              col_type(wide/3, extra, int),
              col_type(narrow/2, id, int), col_type(narrow/2, name, text) ].

check(c4_wider_row_into_a_narrower_head_is_refused,
      ( width_decls(Decls),
        refuses(expand_row_spread_rules(Decls,
                                        [ (narrow(spread(Marker)) <-
                                              wide(spread(Marker))) ],
                                        _),
                head_arity_mismatch(narrow, 3, 2)) )).

check(c4_narrower_row_into_a_wider_head_is_refused,
      ( width_decls(Decls),
        refuses(expand_row_spread_rules(Decls,
                                        [ (wide(spread(Marker)) <-
                                              narrow(spread(Marker))) ],
                                        _),
                head_arity_mismatch(wide, 2, 3)) )).

% The honest half of the same finding: an EQUAL-width splice across two
% different rels is accepted, because the splice is positional and the rel
% identity comes from the functor. It grants nothing that positional
% variables did not already grant.
check(c4_equal_width_cross_rel_splice_is_positional_not_subtyping,
      ( Decls = [ col_type(left/2, id, int), col_type(left/2, name, text),
                  col_type(right/2, key, int), col_type(right/2, label, text) ],
        expand_row_spread_rules(Decls,
                                [ (right(spread(Marker)) <- left(spread(Marker))) ],
                                [ Spliced ]),
        Spliced =@= (right(Id, Name) <- left(Id, Name)) )).

check(c4_the_expansion_never_truncates_or_pads,
      ( width_decls(Decls),
        \+ catch(expand_row_spread_rules(Decls,
                                         [ (narrow(spread(Marker)) <-
                                               wide(spread(Marker))) ],
                                         _),
                 _, fail) )).

% ════════════════════════════════════════════════════════════════════════════
% C5 plane and key inheritance
% ════════════════════════════════════════════════════════════════════════════

keyed_source_program(prog(Decls, Rules)) :-
    Decls = [ col_type(a/2, id, int), col_type(a/2, val, text),
              keyed(a/2, [1]),
              spread_decl(b, [spread(a), col(extra, int)]) ],
    Rules = [ (b(Id, Val, 7) <- a(Id, Val)) ].

check(c5_spread_carries_columns_only,
      ( keyed_source_program(Sugared),
        expand_spread_program(Sugared, prog(Decls, _)),
        forall(member(Decl, Decls),
               ( Decl = col_type(_, _, _) -> true ; Decl = keyed(a/2, [1]) )) )).

check(c5_the_source_key_does_not_cross_the_splice,
      ( keyed_source_program(Sugared),
        expand_spread_program(Sugared, prog(Decls, _)),
        \+ member(keyed(b/_, _), Decls) )).

check(c5_the_source_kind_and_retention_do_not_cross_the_splice,
      ( Sugared = prog([ col_type(a/1, id, int), kind(a/1, log),
                         keep(a/1, count(2)),
                         spread_decl(b, [spread(a), col(extra, int)]) ],
                       []),
        expand_spread_program(Sugared, prog(Decls, _)),
        \+ member(kind(b/_, _), Decls),
        \+ member(keep(b/_, _), Decls) )).

% Graded negative 1: inheriting the source's KEY turns a program the engine
% loads into one it refuses. The engine's own guards (engine.pl:104-107
% keyed_level_head, keyed_log_rel) catch an inherited key in every target
% shape reachable here, so the key hazard shows up as a spurious refusal of
% a valid program rather than as data loss.
check(c5_inheriting_the_key_turns_a_loadable_program_into_a_refusal,
      ( keyed_source_program(Sugared),
        expand_spread_program(Sugared, Selected),
        expand_spread_program_inheriting(Sugared, Inheriting),
        Schedule = [ [ +a(1, "x") ] ],
        run_program(Selected, [], Schedule, _, _),
        catch(( run_program(Inheriting, [], Schedule, _, _), fail ),
              Refusal, true),
        Refusal == keyed_level_head(b/3) )).

% Graded negative 2: inheriting the source's RETENTION is not caught by any
% guard. The inherited keep(count(1)) is placed at the spread point, ahead of
% the author's own keep(all), and decl_keep takes the first match, so the
% target silently retains one row instead of three. This is the shape Go's
% embedding has for methods: the included thing brings behavior along
% (RECEIPTS.md C5, go build refuses only the HAND-COPIED struct, never the
% embedding one).
retention_source_program(prog(Decls, Rules)) :-
    Decls = [ col_type(a/1, val, text), kind(a/1, log), keep(a/1, count(1)),
              spread_decl(b, [spread(a), col(extra, int)]),
              kind(b, log), keep(b, all) ],
    Rules = [ (b(Val, 7) <+ a(Val)) ].

check(c5_inheriting_the_retention_silently_shortens_the_log,
      ( retention_source_program(Sugared),
        expand_spread_program(Sugared, Selected),
        expand_spread_program_inheriting(Sugared, Inheriting),
        Schedule = [ [ +a("x") ], [ +a("y") ], [ +a("z") ] ],
        run_program(Selected, [], Schedule, SelectedFinal, _),
        run_program(Inheriting, [], Schedule, InheritingFinal, _),
        include(is_b_row, SelectedFinal, SelectedRows),
        include(is_b_row, InheritingFinal, InheritingRows),
        length(SelectedRows, 3),
        length(InheritingRows, 1) )).

is_b_row(Row) :- functor(Row, b, _).

% And the retention hazard is INVISIBLE to tick-log-only grading: the two
% programs emit byte-identical delta ticks while their final states differ.
% Same class as the standing retention-grading gap the sweep's final-state
% leg was added for.
check(c5_the_retention_inheritance_is_invisible_in_the_tick_log,
      ( retention_source_program(Sugared),
        expand_spread_program(Sugared, Selected),
        expand_spread_program_inheriting(Sugared, Inheriting),
        Schedule = [ [ +a("x") ], [ +a("y") ] ],
        run_program(Selected, [], Schedule, SelectedFinal, SelectedTicks),
        run_program(Inheriting, [], Schedule, InheritingFinal, InheritingTicks),
        rel_deltas(b/2, SelectedTicks, SelectedDeltas),
        rel_deltas(b/2, InheritingTicks, InheritingDeltas),
        SelectedDeltas == InheritingDeltas,
        \+ ( member(Tick, SelectedDeltas), member(-b(_, _), Tick) ),
        include(is_b_row, SelectedFinal, SelectedRows),
        include(is_b_row, InheritingFinal, InheritingRows),
        length(SelectedRows, 2),
        length(InheritingRows, 1) )).

% ════════════════════════════════════════════════════════════════════════════
% C6 spreading a derived rel
% ════════════════════════════════════════════════════════════════════════════

check(c6_a_derived_rel_is_not_a_legal_spread_source,
      ( Decls = [ spread_decl(b, [spread(pair), col(extra, int)]) ],
        Rules = [ (pair(Id, Tag) <- source(Id, Tag)) ],
        refuses(expand_spread_program(prog(Decls, Rules), _),
                spread_source_not_declared(pair)) )).

% What inference DOES hand back, once the phase that owns it runs. It needs
% Rules plus the surface variable Bindings, neither of which exists where the
% expansion runs (compile.pl:92, engine.pl:349).
check(c6_inference_recovers_columns_only_from_rules_and_bindings,
      ( inferred_columns_for_derived_rel(pair/2, Columns),
        Columns == [id, tag] )).

check(c6_inference_falls_back_to_positional_names,
      ( inferred_columns_for_anonymous_rel(pair/2, Columns),
        Columns == [col1, col2] )).

% Inference gives NAMES and never types; the type pass is a separate
% program-wide fixpoint over literal witnesses (analyze.pl:rel_column_types).
check(c6_inference_gives_no_types_for_a_derived_rel,
      ( inferred_columns_for_derived_rel(pair/2, Columns),
        forall(member(Column, Columns), atom(Column)) )).

% Contrast that draws the real line: GENERATED decls are fine, INFERRED ones
% are not. An enum variant rel carries real col_type entries after enum
% expansion, so it is a legal spread source when the expansions are ordered
% enum-then-spread.
check(c6_an_enum_variant_rel_is_a_legal_spread_source,
      ( enum_generated_columns(body_page, Columns),
        Columns == [col(id, int), col(view, text)] )).

check(c6_the_same_enum_source_is_refused_if_spread_runs_first,
      ( Decls = [ enum_decl(body, (page(view: text) ; redirect(to: text))),
                  spread_decl(wrapped, [spread(body_page), col(extra, int)]) ],
        refuses(expand_spread_program(prog(Decls, []), _),
                spread_source_not_declared(body_page)) )).

% ════════════════════════════════════════════════════════════════════════════
% C7 spread in host declarations
% ════════════════════════════════════════════════════════════════════════════

common_input_decls(Decls) :-
    Decls = [ col_type(common/2, repo, text), col_type(common/2, rev, text),
              col_type(common_out/2, status, int),
              col_type(common_out/2, tag, text) ].

check(c7_host_input_spread_splices_through_the_same_resolver,
      ( common_input_decls(Decls),
        expand_host_decl(Decls,
                         sh_decl(fetch, [spread(common), col(ep, text)],
                                 [col(body, text)],
                                 template("get {repo} {rev} {ep}")),
                         sh_decl(fetch, Inputs, _, _)),
        Inputs == [col(repo, text), col(rev, text), col(ep, text)] )).

check(c7_host_output_spread_splices_independently,
      ( common_input_decls(Decls),
        expand_host_decl(Decls,
                         sh_decl(fetch, [col(ep, text)],
                                 [spread(common_out), col(body, text)],
                                 template("get {ep}")),
                         sh_decl(fetch, _, Outputs, _)),
        Outputs == [col(status, int), col(tag, text), col(body, text)] )).

check(c7_the_input_output_split_survives_the_splice,
      ( common_input_decls(Decls),
        expand_host_decl(Decls,
                         sh_decl(fetch, [spread(common), col(ep, text)],
                                 [spread(common_out)],
                                 template("get {repo} {rev} {ep}")),
                         Expanded),
        compile_host_decl(Expanded,
                          host_plan(fetch,
                                    [col(repo, text), col(rev, text),
                                     col(ep, text)],
                                    [col(status, int), col(tag, text)],
                                    template("get {repo} {rev} {ep}"))) )).

check(c7_a_spliced_input_absent_from_the_template_is_refused,
      ( common_input_decls(Decls),
        expand_host_decl(Decls,
                         sh_decl(fetch, [spread(common), col(ep, text)],
                                 [col(body, text)],
                                 template("get {ep}")),
                         Expanded),
        refuses(compile_host_decl(Expanded, _),
                template_mismatch(unreferenced_input(repo))) )).

check(c7_a_spliced_output_referenced_by_the_template_is_refused,
      ( common_input_decls(Decls),
        expand_host_decl(Decls,
                         sh_decl(fetch, [col(ep, text)],
                                 [spread(common_out)],
                                 template("get {ep} {status}")),
                         Expanded),
        refuses(compile_host_decl(Expanded, _),
                template_mismatch(output_used_as_input(status))) )).

check(c7_a_name_colliding_across_the_two_sides_is_refused,
      ( Decls = [ col_type(common/1, ep, text) ],
        expand_host_decl(Decls,
                         sh_decl(fetch, [spread(common)],
                                 [col(ep, text)],
                                 template("get {ep}")),
                         Expanded),
        refuses(compile_host_decl(Expanded, _),
                column_mismatch(input_output_overlap(ep))) )).

check(c7_the_host_side_needs_no_spread_code_of_its_own,
      ( common_input_decls(Decls),
        spread_columns(Decls, common, ResolverColumns),
        expand_host_decl(Decls,
                         sh_decl(fetch, [spread(common)], [col(body, text)],
                                 template("get {repo} {rev}")),
                         sh_decl(fetch, Inputs, _, _)),
        Inputs == ResolverColumns )).

% ════════════════════════════════════════════════════════════════════════════
% C8 rest and partial application boundary
% ════════════════════════════════════════════════════════════════════════════
% Out of scope by the contract. Recorded as an executable boundary: this
% expansion requires the head to be TOTAL after the splice, so the
% omitted-column shape the kwargs lane owns is refused here rather than
% silently absorbed. The kwargs lane's current exact-fill gate is
% parse_dl.pl:590 fill_free_slots (ledger, USER DIRECTIVES 2026-07-29 late).

check(c8_an_omitted_column_head_is_refused_not_absorbed,
      ( row_decls(Decls),
        refuses(expand_row_spread_rules(Decls,
                                        [ (c(Id) <- a(Id, _Name)) ],
                                        _),
                head_arity_mismatch(c, 1, 3)) )).

check(c8_this_lab_adds_no_wildcard_fill,
      ( row_decls(Decls),
        expand_row_spread_rules(Decls,
                                [ (c(Id, Name, 5) <- a(Id, Name)) ],
                                [ Unchanged ]),
        Unchanged =@= (c(Id2, Name2, 5) <- a(Id2, Name2)) )).

% ════════════════════════════════════════════════════════════════════════════
% Spelling pricing
% ════════════════════════════════════════════════════════════════════════════
% Candidate A: `rel b(...a, extra: int).`  spread marker inside the column list
% Candidate B: `rel b(extra: int) include a.`  a separate decl clause
% Candidate C: term form only, no .dl6 surface at all
%
% The criterion that separates A from B is executable: column order is
% significant (ruling decl_column_spelling = colon_typed_ordered_columns), and
% an include clause has no place to say WHERE the source columns land.

include_projection(spread_decl(_, Spec), Sources-Explicit) :-
    findall(Source, member(spread(Source), Spec), Sources),
    findall(col(Column, Type), member(col(Column, Type), Spec), Explicit).

check(pricing_include_clause_cannot_state_the_splice_point,
      ( base_decls(Base),
        Leading = spread_decl(b, [spread(a), col(extra, int)]),
        Trailing = spread_decl(b, [col(extra, int), spread(a)]),
        append(Base, [Leading], LeadingDecls),
        append(Base, [Trailing], TrailingDecls),
        expand_spread_program(prog(LeadingDecls, []), prog(LeadingOut, _)),
        expand_spread_program(prog(TrailingDecls, []), prog(TrailingOut, _)),
        findall(C, member(col_type(b/3, C, _), LeadingOut), LeadingColumns),
        findall(C, member(col_type(b/3, C, _), TrailingOut), TrailingColumns),
        LeadingColumns == [id, name, extra],
        TrailingColumns == [extra, id, name],
        LeadingColumns \== TrailingColumns,
        include_projection(Leading, Projection),
        include_projection(Trailing, Projection) )).

check(pricing_term_form_only_has_no_registry_row_and_no_text_door,
      ( \+ surface(spread_decl/2, _, _, _, _),
        \+ surface(spread/1, _, _, _, _) )).

% Candidate A costs exactly one registry row shape and zero downstream
% knowledge, because the expansion output is ordinary decl entries. That is
% the same property the enum and match expansions have, checked here against
% the real registry: neither enum_decl nor match is known to any phase past
% its expansion, yet both carry a live registry row.
check(pricing_the_expansion_precedent_carries_a_live_registry_row,
      ( surface(enum_decl/2, decl, _, _, live),
        surface(match/2, sugar, _, _, live) )).
